// Pattern Break Watchlist data — chart patterns being tracked per stock.
// Percentages in the UI are measured from `price` (the close on `priceDate`),
// not from the stock file's `currentPrice`.
//
// direction: "down" | "up" | "both" ("both" = no break yet; uses breakUp/breakDown/goalUp/goalDown)
// stage:     "forming" | "signal" | "confirmed" | "target" | "failed" | "update"
//            "update" = needs updating: a pending setup closed past one of its limits;
//            prevStage / updateDate / updateNote record what it was, when, and what broke
//            (set by pattern_watchlist.py; stageDate keeps the date of the previous stage).

export type PatternDirection = 'up' | 'down' | 'both';
/** 'retest' is a confirmed break that has come back to the broken boundary and is
 *  being tested. It behaves as confirmed everywhere -- same levels, same target and
 *  failure checks -- and only reads differently. See PATTERN_RULES.md section 1. */
/** 'atRisk' is a confirmed break whose price has closed back past its own invalidation,
 *  once. Failure needs a follow-through close, so the break is not dead -- but it is no
 *  longer working, and the row says so. The price run sets it and clears it again if the
 *  next close comes back inside; prevStage / updateDate hold what it was and when it went. */
export type PatternStage = 'forming' | 'signal' | 'confirmed' | 'retest' | 'atRisk' | 'target' | 'failed' | 'update';
export type PatternTimeframe = 'daily' | 'weekly' | 'monthly';
/** Direction of the stock's own trend, from ~3 months of daily bars (pattern_watchlist._trend).
 *  Setups pointing the same way are listed first; 'flat' leaves the stored order alone. */
export type PatternTrend = 'up' | 'down' | 'flat';

// Optional trendline anchors for the chart: [date 'YYYY-MM-DD', price] pairs.
export type PatternLine = { from: [string, number]; to: [string, number] };

// Stored setups in the same direction whose target is within 5% (computed by pattern_watchlist.py).
export type PatternAgree = { n: number; lo: number; hi: number; with: string[] };

export interface PatternAltSetup {
  auto?: boolean;
  /** Same as PatternStock.tag: a per-setup label, rendered from whichever setup the row
   *  shows. It lives here too so a main setup demoted into this slot keeps it. */
  tag?: string;
  /** See PatternStock.dormant: shelved, hidden from the ledger, woken by a close back
   *  past the break. Lives on the setup rather than the stock, since one stock can hold
   *  a stale reading and a live one at the same time. */
  dormant?: boolean;
  dormantSince?: string;
  dormantNote?: string;
  agree?: PatternAgree;
  pattern?: string;
  timeframe: PatternTimeframe;
  flag?: string;
  direction: PatternDirection;
  stage: PatternStage;
  stageDate?: string;
  prevStage?: PatternStage;
  updateDate?: string;
  updateNote?: string;
  signal?: number;
  confirm?: number;
  invalidation?: number;
  /** The invalidation as it stood on the day of the break, written once by
   *  pattern_lines.freeze_stops() and never re-read: `invalidation` walks with its
   *  trendline, so only this says what being wrong would have cost on entry. */
  breakInvalidation?: number;
  /** A stop sheltered behind the nearest band of agreed price beyond the entry,
   *  read off the time-at-price profile of the candles BEFORE the break
   *  (price_profile.write_stops). Nothing ranks on it. It is recorded because it
   *  is the only stop on the row that does not walk with a trendline: of the
   *  confirmed setups still shown live, price had already traded through the
   *  frozen stop on 141 of 319 and through this one on 50 of 230. */
  profileStop?: number;
  target?: number;
  breakUp?: number;
  breakDown?: number;
  goalUp?: number;
  goalDown?: number;
  signalRule?: string;
  confirmRule?: string;
  failRule?: string;
  note?: string;
  lines?: PatternLine[];
}

export interface PatternHistoryEntry {
  pattern: string;
  timeframe: PatternTimeframe;
  direction: 'up' | 'down';
  stage: PatternStage;
  stageDate: string;
  /** Absent on a setup that failed while still forming: it never signalled, so no
   *  confirm level was ever set and no measured move was ever projected. Only the
   *  invalidation it died on and the signal it never reached are known. */
  confirm?: number;
  signal?: number;
  invalidation: number;
  target?: number;
  note?: string;
}

export interface PatternStock {
  ticker: string;
  name: string;
  auto?: boolean;              // auto-detected by pattern_detect.py: red dot until checked by hand
  /** Date this stock's setups were last checked against the charts by hand. Shows a
   *  green dot while a print is still ahead of it, and stops showing once that print
   *  has happened: a check made before the numbers is stale after them. */
  checkedOn?: string;
  /** Shelved: still valid, but old enough and far enough undone that showing it misleads.
   *  Hidden from the ledger and kept in the data, not moved to `history` — that array is
   *  the record of COMPLETED calls pattern_reproduce.py trains on, and a setup that never
   *  resolved is not a label. The daily run wakes it the moment price closes back past the
   *  confirm level in the setup's own direction. */
  dormant?: boolean;
  dormantSince?: string;
  dormantNote?: string;
  trend?: PatternTrend;        // the stock's own trend; orders the setup list
  rsi?: number;                // daily Wilder RSI-14; >=60 bullish, <=40 bearish momentum
  agree?: PatternAgree;
  pattern: string;
  timeframe: PatternTimeframe;
  flag?: string;
  tag?: string;
  direction: PatternDirection;
  stage: PatternStage;
  stageDate?: string;
  prevStage?: PatternStage;
  updateDate?: string;
  updateNote?: string;
  price: number;
  priceDate: string;
  signal?: number;
  confirm?: number;
  invalidation?: number;
  /** The invalidation as it stood on the day of the break, written once by
   *  pattern_lines.freeze_stops() and never re-read: `invalidation` walks with its
   *  trendline, so only this says what being wrong would have cost on entry. */
  breakInvalidation?: number;
  /** A stop sheltered behind the nearest band of agreed price beyond the entry,
   *  read off the time-at-price profile of the candles BEFORE the break
   *  (price_profile.write_stops). Nothing ranks on it. It is recorded because it
   *  is the only stop on the row that does not walk with a trendline: of the
   *  confirmed setups still shown live, price had already traded through the
   *  frozen stop on 141 of 319 and through this one on 50 of 230. */
  profileStop?: number;
  target?: number;
  breakUp?: number;
  breakDown?: number;
  goalUp?: number;
  goalDown?: number;
  signalRule?: string;
  confirmRule?: string;
  failRule?: string;
  note?: string;
  lines?: PatternLine[];
  keyLevel?: { price: number; text: string };
  alt?: PatternAltSetup;
  history?: PatternHistoryEntry[];
  // Up to 5 setups are stored per stock; only the most valid (the main one) is shown.
  // The rest feed the "N agree" confidence badge when their targets match.
  more?: PatternAltSetup[];
}

